import{_ as r,o as a,c as o,ao as t}from"./chunks/framework.CjHcmwhZ.js";const m=JSON.parse('{"title":"Related Work","description":"","frontmatter":{},"headers":[],"relativePath":"man/related_work.md","filePath":"man/related_work.md","lastUpdated":null}'),i={name:"man/related_work.md"};function n(s,e,l,d,p,c){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="Related-Work" tabindex="-1">Related Work <a class="header-anchor" href="#Related-Work" aria-label="Permalink to &quot;Related Work {#Related-Work}&quot;">​</a></h1><p>Thermal-kinematic codes such as the one presented here have been around for some time, with various degrees of sophistication ([1], [2], [3], [4]). A recent effort in Julia, similar to this package, is described in [5].</p><p>As far as we are aware, source code of many older tools is not openly available in non-binary form, which makes direct implementation comparisons difficult. No existing package in this specific category combines 3D workflows with GPU acceleration in the same way.</p><p>[1] Dufek, J., and Bergantz, G. W. (2005). Lower crustal magma genesis and preservation: A stochastic framework for the evaluation of basalt-crust interaction. Journal of Petrology, 46(11), 2167-2195. <a href="https://doi.org/10.1093/petrology/egi049" target="_blank" rel="noreferrer">https://doi.org/10.1093/petrology/egi049</a></p><p>[2] Annen, C., Blundy, J. D., and Sparks, R. S. J. (2006). The genesis of intermediate and silicic magmas in deep crustal hot zones. Journal of Petrology, 47(3), 505-539. <a href="https://doi.org/10.1093/petrology/egi084" target="_blank" rel="noreferrer">https://doi.org/10.1093/petrology/egi084</a></p><p>[3] Caricchi, L., Annen, C., Blundy, J., Simpson, G., and Pinel, V. (2014). Frequency and magnitude of volcanic eruptions controlled by magma injection and buoyancy. Nature Geoscience, 7, 126-130. <a href="https://doi.org/10.1038/NGEO2041" target="_blank" rel="noreferrer">https://doi.org/10.1038/NGEO2041</a></p><p>[4] Tierney, C. R., Schmitt, A. K., Lovera, O. M., and de Silva, S. L. (2016). Voluminous plutonism during a period of volcanic quiescence revealed by thermochemical modeling of zircon. Geology, 44, 683-686. <a href="https://doi.org/10.1130/G37968.1" target="_blank" rel="noreferrer">https://doi.org/10.1130/G37968.1</a></p><p>[5] Melnik, O. E., Utkin, I. S., and Bindeman, I. N. (2021). Magma Chamber Formation by Dike Accretion and Crustal Melting: 2D Thermo-Compositional Model With Emphasis on Eruptions and Implication for Zircon Records. J Geophys Res Solid Earth, 126. <a href="https://doi.org/10.1029/2021JB023008" target="_blank" rel="noreferrer">https://doi.org/10.1029/2021JB023008</a></p><p>[6] Degruyter, W., and Huber, C. (2014). A model for eruption frequency of upper crustal silicic magma chambers. Earth and Planetary Science Letters, 403, 117-130. <a href="https://doi.org/10.1016/j.epsl.2014.06.047" target="_blank" rel="noreferrer">https://doi.org/10.1016/j.epsl.2014.06.047</a> — the physical overpressure eruption trigger (see <a href="./eruptions">Eruptions</a>) implements this model.</p>',9)])])}const g=r(i,[["render",n]]);export{m as __pageData,g as default};
